using System;using System.IO;using System.Text;using System.Net;using System.Linq;using System.Reflection;using System.Runtime.Serialization.Json;
using GlassBoard;
class CompatibilityTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static GeoReply Geo(string url){return new GeoReply{Results=new System.Collections.Generic.List<GeoPlace>{new GeoPlace{Name="测试城",Country="中国",Latitude=30,Longitude=120}}};}
 static WttrReply Backup(string url){Check(url.StartsWith("https://wttr.in/"),"backup HTTPS route");return new WttrReply{Current=new System.Collections.Generic.List<WttrCurrent>{new WttrCurrent{Temperature="18.5",Wind="12",Chinese=new System.Collections.Generic.List<WttrText>{new WttrText{Value="多云"}}}},Areas=new System.Collections.Generic.List<WttrArea>{new WttrArea{Latitude="30",Longitude="120",Name=new System.Collections.Generic.List<WttrText>{new WttrText{Value="测试城"}},Country=new System.Collections.Generic.List<WttrText>{new WttrText{Value="中国"}}}}};}
 static int Main(string[] args){
  Check(WeatherClient.NormalizeCity(" 浙江省杭州市 ")=="杭州","province and city suffix");Check(WeatherClient.NormalizeCity("Paris， France")=="Paris, France","explicit country qualifier");
  GeoPlace point;Check(WeatherClient.Coordinates("30.2,120.1",out point)&&point.Latitude==30.2,"manual coordinates");Check(!WeatherClient.Coordinates("NaN,120",out point)&&!WeatherClient.Coordinates("91,120",out point)&&!WeatherClient.Coordinates("30,Infinity",out point),"invalid coordinates rejected");
  int backupCalls=0;var primary=WeatherClient.Fetch("热修复测试城",Geo,url=>new WeatherReply{Current=new WeatherCurrent{Temperature=12}},url=>{backupCalls++;return Backup(url);});Check(primary.Provider=="Open-Meteo"&&backupCalls==0,"primary success does not call backup");
  var fallback=WeatherClient.Fetch("热修复测试城",Geo,url=>{throw new WebException("timeout",WebExceptionStatus.Timeout);},Backup);Check(fallback.Provider=="wttr.in"&&fallback.Current.Temperature==18.5&&fallback.Current.Description=="多云","forecast timeout uses backup weather and actual description");
  var geoFallback=WeatherClient.Fetch("不存在的定位测试城",url=>{throw new WebException("DNS",WebExceptionStatus.NameResolutionFailure);},url=>{throw new Exception("must not call forecast");},Backup);Check(geoFallback.Place.Name=="测试城","geocoding failure also reaches backup");
  var normalized=WeatherClient.Fetch("自动去后缀测试市",url=>{Check(Uri.UnescapeDataString(url).Contains("name=自动去后缀测试"),"normalized city in URL");return Geo(url);},url=>new WeatherReply{Current=new WeatherCurrent()},Backup);
  try{WeatherClient.FromWttr(new WttrReply());throw new Exception("accepted empty weather");}catch(InvalidDataException){}
  var malformed=Backup("https://wttr.in/test");malformed.Current[0].Temperature="NaN";try{WeatherClient.FromWttr(malformed);throw new Exception("accepted malformed temperature");}catch(InvalidDataException){}
  try{WeatherClient.Fetch("失败测试城",url=>{throw new WebException("bad",WebExceptionStatus.Timeout);},url=>null,url=>{throw new WebException("bad",WebExceptionStatus.NameResolutionFailure);});throw new Exception("swallowed complete outage");}catch(InvalidOperationException ex){Check(ex.Message.Contains("主服务：")&&ex.Message.Contains("备用服务："),"separate provider errors");}
  var panel=new WidgetPanelPosition{Width=260,Height=150};panel.Normalize();Check(panel.Width==260&&panel.Height==150,"compact custom sizing survives normalization");panel.CompactWeatherWidth=100;using(var buffer=new MemoryStream()){var json=new DataContractJsonSerializer(typeof(WidgetPanelPosition));json.WriteObject(buffer,panel);buffer.Position=0;var restored=(WidgetPanelPosition)json.ReadObject(buffer);restored.Normalize();Check(restored.CompactWeatherWidth==100&&restored.Width==260,"small weather width survives restart without changing regular width");restored.CompactWeatherWidth=2;restored.Normalize();Check(restored.CompactWeatherWidth==96,"small weather width lower bound");}Check(WidgetSizing.MinimumHeight(200,800)>=140&&WidgetSizing.MinimumHeight(200,800)<200,"compact height floor");Check((ShellStylePolicy.ToolStyle(0x40000|0x80000)&0x80)!=0&&(ShellStylePolicy.ToolStyle(0x40000|0x80000)&0x40000)==0&&(ShellStylePolicy.ToolStyle(0x80000)&0x80000)!=0,"tool window excludes app list and retains layered style");
  var motion=DockRevealRules.Stops(1000,880,1,0);Check(motion[0]==1000&&motion[1]<880&&motion[2]>880&&motion[3]==880,"spring starts at displayed position, overshoots, settles at exact target");Check(DockRevealRules.Stops(100,0,1,0)[1]==0,"spring stays inside screen top");
  var options=new DockOptions{SpringReveal=false};using(var buffer=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(DockOptions));serializer.WriteObject(buffer,options);buffer.Position=0;var restored=(DockOptions)serializer.ReadObject(buffer);Check(!restored.SpringReveal&&!restored.Copy().SpringReveal,"spring off persists and copies");}using(var buffer=new MemoryStream(Encoding.UTF8.GetBytes("{}"))){var legacy=(DockOptions)new DataContractJsonSerializer(typeof(DockOptions)).ReadObject(buffer);Check(legacy.SpringReveal,"legacy preferences receive spring default");}
  var assembly=Assembly.LoadFile(Path.GetFullPath(args[0]));foreach(string name in new[]{"MediaBridge.ps1","NativeMediaBridge.ps1"})using(var stream=assembly.GetManifestResourceStream("GlassBoard."+name)){Check(stream!=null,"embedded bridge "+name);using(var reader=new StreamReader(stream))Check(reader.ReadToEnd().Contains("[Console]::ReadLine()"),"embedded protocol "+name);}
  Check(assembly.GetName().Version.ToString()=="0.2.0.0","actual release version");
  Check(!assembly.GetReferencedAssemblies().Any(a=>a.Name=="Interop.UIAutomationClient"),"standalone COM interop assembly is not a runtime dependency");
  Console.WriteLine("PASS: production weather primary/backup/failures/normalization/coordinates/data validation, compact persisted sizing, shell styles, embedded media modules and actual executable version");return 0;
 }
}
